    return white, black

def max_distance(color_list):
    if not color_list:
        return 0
    q = deque(color_list)
    visited = set()
    steps = 0
    while q:
        size = len(q)
        while size > 0:
            current = q.popleft()
            if current in visited:
                continue
            visited.add(current)
            size -= 1
            for neighbor in adj[current]:
                if neighbor not in visited:
                    q.append(neighbor)
        steps += 1
    return steps - 1

