from collections import defaultdict, deque

MOD = 10**9 + 7

def bfs(graph, start):
    n = len(graph)
    dist = [-1] * n
    dist[start] = 0
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return max(dist) if any(dist) else 0

def dfs(graph, u, parent, color_count):
    max_dist_same_color = max(bfs(graph, v) for v in range(len(graph)) if v != u and v not in color_count) if color_count else 0
    max_dist_diff_color = max(bfs(graph, v) for v in range(len(graph)) if v != u and v in color_count) if color_count else 0
    return [max(max_dist_same_color, max_dist_diff_color), sum(color_count.values())]

def solve():
    n = int(input().strip())
    graph = defaultdict(list)
    for _ in range(n - 1):
        a, b = map(int, input().strip().split())
        a -= 1
        b -= 1
        graph[a].append(b)
        graph[b].append(a)

    def helper(u, parent):
        result = [0, 0]
        for v in graph[u]:
            if v != parent:
                sub_result = helper(v, u)
                result[0] += sub_result[0]
                result[1] += sub_result[1]
        return dfs(graph, u, parent, {u})

